[{"name":"mcp__agdf__agdf_dispatch","description":"Run the version-matched AGDF preflight for one canonical skill. It resolves target and control state but never grants approval or delivery authority. Only authorized bound continue_delivery may record one previously sealed relationship correction through the Core continuation service before fresh routing; status stays read-only. For a result with `terminal: true`, the entire assistant response must consist only of host_action.text, copied verbatim. Add no question, explanation, heading, citation, link or other surrounding text; do not translate or reformat it; invoke no later tool and stop. For skill_continuation, follow its continuation instruction using only the returned target and control. For intake_continuation phase resolve_delivery_run, match the request to supplied UR scope evidence; resume one same-scope run with its expected_revision_id, or start a clear new scope. Ask only about genuinely ambiguous work, never for technical Run IDs. Other phases execute continuation.steps in order; presentation_required shows run-present text and waits for a NEW deliberate response. Preparation approves no gate. This tool is part of plugin `AI Governance & Delivery Framework`.

exec tool declaration:
```ts
declare const tools: { mcp__agdf__agdf_dispatch(args: {
  // Set only with skill_id gate-check for an authorized bound delivery continuation, including after a valid UR, PRD, SD, TP or UAT approval. Requires run_id; incompatible with intake. Never set on a returned judgement skill or for status or advice. Allows canonical Brownfield Review / Mode-Slice recovery, implementation-preparation Brownfield Analysis after TP approval, missing PRD/SD/TP preparation before approval cards, permitted compact implementation/closeout, and OR closeout after UAT approval. Completed Runs stop; no VCS authority is implied.
  continue_delivery?: boolean;
  // Revision from the resolve_delivery_run candidate used for scope matching. Requires intake true, intake_mode resume and run_id. Changed or unavailable binding returns fresh assignment evidence before gate evaluation; it never adopts another run automatically.
  expected_revision_id?: string;
  // Set true only with skill_id gate-check when the governed delivery intake (catalog delivery.start) is the active route; delivery wins mixed intent, so a gate-check invocation that asks for a change also sets it. Omit it for status, approval or next-step questions. It never grants approval or delivery authority.
  intake?: boolean;
  // With intake true: new prepares the explicitly authorized new scope at an unused run_id; resume continues the bound run. Requires run_id. Never infer new from ambiguous continuation.
  intake_mode?: "new" | "resume";
  // Explicit ur-definition planning mode before any Run. Use one selected plan and source digest (null for capture); no delivery intake or gate approval.
  planning?: { expected_digest: string | null; plan_id: string; };
  // Explicit user intent to revise the bound unapproved PRD. Requires gate-check, intake true, intake_mode resume, run_id and expected_revision_id; never approval.
  prd_action?: "revise";
  // MCP reply-language override (BCP 47). Omit for a matching configured preference; otherwise supply the current request's language (explicit instruction, then dominant language, en if ambiguous). Invalid explicit tags fail; valid unsupported tags use the complete English pack. Core input remains complete.
  presentation_language?: string;
  // Absolute governance-target path paired with target_source. Never derive it from working_directory alone.
  primary_target?: string;
  // Canonical run identifier. Select an existing run from an explicit request, confirmed continuation or unequivocal same-scope assignment after resolve_delivery_run. Scope assignment must use expected_revision_id. For intake_mode new, choose an unused id for the authorized change; never reuse an existing run.
  run_id?: string;
  // Explicit user intent to revise the bound unapproved SD. Requires gate-check, intake true, intake_mode resume, run_id and expected_revision_id; never approval.
  sd_action?: "revise";
  // Canonical AGDF skill slug or exact catalog-registered skill name for the calling host; normalized internally to the stable canonical ID.
  skill_id: string;
  // Authority source for primary_target. Supply it only with primary_target and only when exactly one listed meaning applies; otherwise omit both fields.
  target_source?: "explicit_target" | "continued_target" | "current_repository";
  // Explicit user intent to revise the bound unapproved TP. Requires gate-check, intake true, intake_mode resume, run_id and expected_revision_id; never approval.
  tp_action?: "revise";
  // Explicit user intent to revise the bound unapproved UR. Requires gate-check, intake true, intake_mode resume, run_id and expected_revision_id; never approval.
  ur_action?: "revise";
  // Absolute execution-context path. It never selects or authorizes a target.
  working_directory?: string;
}): Promise<CallToolResult<{
  authorizes: false;
  continuation: { [key: string]: unknown; } | null;
  contract_version: 1;
  // For a qa-gate skill_continuation, control.candidate_runs is the complete canonical active-run inventory when run selection is unresolved, otherwise an empty array. Use its run_id, objective, normalized current_gate, decision and revision_id fields as data; filter by current_gate: QA and do not rescan run files, invent candidates or omit returned QA candidates.
  control: { [key: string]: unknown; } | null;
  diagnostics: Array<{ [key: string]: unknown; }>;
  host_action: { [key: string]: unknown; } | null;
  outcome: "invalid_input" | "target_unresolved" | "control_result" | "skill_continuation" | "intake_continuation" | "evaluator_error";
  // Canonical Markdown for terminal results. For presentation_required it is the read-only approval_preview of the current gate (same digests as run-present); it binds nothing, so still run the supplied run-present step and ask the gate question only after its presentation_id exists.
  presentation: { [key: string]: unknown; } | null;
  recovery: { [key: string]: unknown; } | null;
  runtime: { [key: string]: unknown; };
  schema_version: "1";
  skill: { [key: string]: unknown; } | null;
  target: { [key: string]: unknown; } | null;
  terminal: boolean;
  timing: { control_ms: number; input_ms: number; render_ms: number; target_ms: number; total_ms: number; wrapper_ms: number; };
}>>; };
